CREATE TABLE IF NOT EXISTS schema_versions(version int PRIMARY KEY, applied_at timestamptz DEFAULT now());
CREATE TABLE workspaces(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,username text UNIQUE NOT NULL,name text NOT NULL,email text DEFAULT '',role text NOT NULL CHECK(role IN('superadmin','admin','member')),active boolean NOT NULL DEFAULT true,password_hash text NOT NULL,must_change boolean NOT NULL DEFAULT true,mfa_secret text,mfa_pending text,mfa_enabled boolean NOT NULL DEFAULT false,mfa_step bigint NOT NULL DEFAULT -1,recovery_hashes jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),mfa_verified boolean NOT NULL DEFAULT false);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE reset_tokens(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL);
CREATE TABLE settings(workspace_id uuid PRIMARY KEY REFERENCES workspaces,revision int NOT NULL DEFAULT 0,value jsonb NOT NULL DEFAULT '{"cloudConsent":false,"riskConsent":false,"globalAuto":false,"providerId":"","tone":"简洁、自然、专业，不冒充真人","language":"跟随客户","companyInfo":"","boundaries":"价格、付款、投诉、退订或要求人工时转人工；禁止捏造承诺","maxRepliesPerHour":20}');
CREATE TABLE providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,name text NOT NULL,base_url text NOT NULL,model text NOT NULL,key_cipher text NOT NULL,tested boolean NOT NULL DEFAULT false);
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,name text NOT NULL,owner_id uuid REFERENCES users,enabled boolean NOT NULL DEFAULT false,auto_reply boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'disconnected',qr text,phone text,settings jsonb NOT NULL DEFAULT '{}',lease_owner text,lease_until timestamptz,generation bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_grants(account_id uuid NOT NULL REFERENCES accounts,user_id uuid NOT NULL REFERENCES users,PRIMARY KEY(account_id,user_id));
CREATE TABLE wa_auth(account_id uuid NOT NULL REFERENCES accounts,key text NOT NULL,value text NOT NULL,PRIMARY KEY(account_id,key));
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,account_id uuid NOT NULL REFERENCES accounts,jid text NOT NULL,name text NOT NULL,assignee_id uuid REFERENCES users,mode text NOT NULL DEFAULT 'AUTO' CHECK(mode IN('AUTO','HUMAN','PAUSED')),revision int NOT NULL DEFAULT 0,country text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',tags jsonb NOT NULL DEFAULT '[]',analysis jsonb,summary jsonb,presence text DEFAULT 'unknown',presence_at timestamptz,avatar_id uuid,deleted_at timestamptz,merged_into uuid REFERENCES conversations,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),last_text text NOT NULL DEFAULT '',UNIQUE(account_id,jid));
CREATE INDEX conversations_inbox ON conversations(workspace_id,updated_at DESC,id);
CREATE INDEX conversations_assigned ON conversations(assignee_id,account_id);
CREATE TABLE identities(account_id uuid NOT NULL REFERENCES accounts,jid text NOT NULL,conversation_id uuid NOT NULL REFERENCES conversations,PRIMARY KEY(account_id,jid));
CREATE TABLE folders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,name text NOT NULL,UNIQUE(workspace_id,name));
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,conversation_id uuid REFERENCES conversations,folder_id uuid REFERENCES folders,name text NOT NULL,mime text NOT NULL,bytes int NOT NULL,hash text NOT NULL,extracted_text text NOT NULL DEFAULT '',ai_readable boolean NOT NULL DEFAULT false,reply_usable boolean NOT NULL DEFAULT false,external boolean NOT NULL DEFAULT false,extraction_status text NOT NULL DEFAULT 'pending',preview_id uuid REFERENCES assets,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_library ON assets(workspace_id,folder_id,created_at DESC) WHERE conversation_id IS NULL;
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,account_id uuid NOT NULL REFERENCES accounts,conversation_id uuid NOT NULL REFERENCES conversations,platform_id text NOT NULL,direction text NOT NULL CHECK(direction IN('in','out')),text text NOT NULL DEFAULT '',kind text NOT NULL DEFAULT 'text',asset_id uuid REFERENCES assets,historical boolean NOT NULL DEFAULT false,translation text,sent_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'received',UNIQUE(account_id,platform_id,direction));
CREATE INDEX messages_page ON messages(conversation_id,sent_at DESC,id);
CREATE TABLE drafts(conversation_id uuid NOT NULL REFERENCES conversations,user_id uuid NOT NULL REFERENCES users,text text NOT NULL DEFAULT '',revision int NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,conversation_id uuid REFERENCES conversations,user_id uuid REFERENCES users,kind text NOT NULL,status text NOT NULL DEFAULT 'queued',revision int,settings_revision int,payload jsonb NOT NULL DEFAULT '{}',result jsonb,error text,progress int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON jobs(status,created_at);
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces,conversation_id uuid NOT NULL REFERENCES conversations,account_id uuid NOT NULL REFERENCES accounts,user_id uuid REFERENCES users,idempotency_key text NOT NULL,request_hash text NOT NULL,text text NOT NULL DEFAULT '',asset_id uuid REFERENCES assets,automatic boolean NOT NULL DEFAULT false,revision int NOT NULL,settings_revision int,status text NOT NULL DEFAULT 'queued',error text,platform_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,idempotency_key));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces,user_id uuid REFERENCES users,action text NOT NULL,resource text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE maintenance(id int PRIMARY KEY CHECK(id=1),active boolean NOT NULL DEFAULT false);
INSERT INTO maintenance VALUES(1,false);
CREATE FUNCTION app_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT current_setting('app.role',true) IN ('superadmin','admin') $$;
CREATE FUNCTION app_workspace() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.workspace',true),'')::uuid $$;
CREATE FUNCTION app_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_scope ON conversations TO smarchat_api USING(workspace_id=app_workspace() AND (app_admin() OR (assignee_id=app_user() AND EXISTS(SELECT 1 FROM account_grants g WHERE g.account_id=conversations.account_id AND g.user_id=app_user()))));
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_scope ON messages TO smarchat_api USING(workspace_id=app_workspace() AND EXISTS(SELECT 1 FROM conversations c WHERE c.id=messages.conversation_id));
ALTER TABLE assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY assets_scope ON assets TO smarchat_api USING(workspace_id=app_workspace() AND (conversation_id IS NULL OR EXISTS(SELECT 1 FROM conversations c WHERE c.id=assets.conversation_id)));
ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY jobs_scope ON jobs TO smarchat_api USING(workspace_id=app_workspace() AND (app_admin() OR (user_id=app_user() AND (conversation_id IS NULL OR EXISTS(SELECT 1 FROM conversations c WHERE c.id=jobs.conversation_id)))));
ALTER TABLE outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY outbox_scope ON outbox TO smarchat_api USING(workspace_id=app_workspace() AND EXISTS(SELECT 1 FROM conversations c WHERE c.id=outbox.conversation_id));
ALTER TABLE drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY drafts_scope ON drafts TO smarchat_api USING(user_id=app_user() AND EXISTS(SELECT 1 FROM conversations c WHERE c.id=drafts.conversation_id));
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_scope ON audit_events TO smarchat_api USING(workspace_id=app_workspace() AND (app_admin() OR user_id=app_user()));
GRANT USAGE ON SCHEMA public TO smarchat_api,smarchat_worker;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO smarchat_api,smarchat_worker;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO smarchat_api,smarchat_worker;
REVOKE UPDATE,DELETE ON audit_events FROM smarchat_api,smarchat_worker;
INSERT INTO schema_versions VALUES(1,now());
